dict(slug="debt-consolidation-and-balance-transfer", name="Debt Consolidation & Balance Transfer", icon="merge",
 tag="Lower your EMIs, merge multiple debts and move to a cheaper lender with clear savings maths.",
 intro=["Refinancing helps when you already have loans or card dues costing more than they should. A balance transfer moves an existing loan to a lender offering a lower rate. Debt consolidation combines several debts into one loan with a single EMI. Loan restructuring renegotiates terms when repayment becomes hard.",
        "The saving is not automatic: processing fees, foreclosure charges and a longer tenure can wipe out a rate gain. NEXUS helps you compare the true total cost before and after, and connect with partner lenders. We encourage you to ask your existing lender for a rate cut first."],
 amount="Equal to your outstanding balance, plus any top-up", tenure="As per the new loan", rate="Varies by loan type, credit score and lender.",
 security="Same as the underlying loan type (secured or unsecured)",
 who=["Borrowers paying a high interest rate", "People juggling several EMIs and card dues", "Borrowers needing a top-up along with the transfer"],
 features=["Potential interest saving over the remaining tenure", "One EMI instead of several", "Optional top-up for extra funds", "Chance to switch from fixed to floating or vice versa"],
 elig=["Good repayment track record on the existing loan (usually 6 to 12 EMIs paid)", "Credit score 700+ for the best offers", "Stable income", "Clean property papers (for secured loans)"],
 docs=["Existing loan statement and sanction letter", "Foreclosure letter from the current lender", "KYC and income documents", "Property documents (for secured loans)", "Bank statements for 6 months"],
 fees=["Processing fee on the new loan", "Foreclosure charges on the old loan (nil on floating-rate loans to individuals as per RBI norms)", "Legal and valuation fees for secured loans"],
 tips=["Calculate savings over the remaining tenure, not only the EMI drop", "Avoid extending tenure unnecessarily", "Ask your current lender to match the rate", "Do not add new debt after consolidation"],
 faqs=[("When is a balance transfer worthwhile?","When the rate difference is meaningful, enough tenure remains and total fees are low. Use our balance transfer calculator."),
       ("Will my credit score drop?","A new loan application triggers an enquiry, and closing old loans can change your credit mix. Timely repayment later usually improves the score."),
       ("Can I consolidate credit card dues?","Yes, using a personal loan, usually at lower rates than revolving credit card interest, provided you stop using the card for new revolving debt."),
       ("What is loan restructuring?","Renegotiating the tenure or EMI with your lender when you face difficulty, which may affect your credit report.")],
 wa=["Which loans you have (type, outstanding, rate, EMI)", "Remaining tenure", "Whether you need a top-up", "Monthly income and city"],
 related=["personal-loan","home-loan","loan-against-property","business-loan"],
 subs=[
  S("personal-loan-balance-transfer","Personal Loan Balance Transfer","Move an unsecured personal loan to a lender with a lower rate. Savings depend on the remaining tenure and fees.","Borrowers with high-rate personal loans and good repayment records.","Do this only when the rate gap covers fees.","How long should I wait before transferring?","Many lenders want 6 to 12 EMIs paid on time."),
  S("credit-card-debt-consolidation","Credit Card Debt Consolidation","Replace revolving credit card balances with a fixed-EMI personal loan, which usually costs less than card interest.","Cardholders carrying balances month to month.","Stop using the card for new revolving debt.","Will the cards be closed?","You choose. Keeping a zero-balance card open can help your credit history."),
  S("multiple-emi-consolidation","Multiple EMI Consolidation","Merge several loans into one with a single EMI and due date, simplifying management and often lowering the monthly outgo.","Borrowers with 3+ separate EMIs.","Check that the new total cost is lower, not just the EMI.","Is a longer tenure bad?","It lowers EMI but increases total interest."),
  S("business-loan-refinancing","Business Loan Refinancing","Replace expensive business debt with a cheaper loan, often by providing security or showing stronger financials.","Businesses whose profile has improved since the original loan.","Show improved turnover, ITR and credit history.","Can I add working capital while refinancing?","Often yes, through a top-up."),
  S("loan-restructuring-and-takeover","Loan Restructuring and Takeover Loan","Restructuring renegotiates terms with your lender. A takeover loan has a new lender paying off the old.","Borrowers facing repayment strain, or wanting better terms.","Talk to the lender early; early restructuring is easier.","Does restructuring hurt my score?","It can be noted in your credit report. Compare alternatives."),
 ]),
